from lib import *
S = SS('p68')
steps = [
    step("客户端匀速每秒 30 个请求发 3 秒(共 90 个),服务器限制 10 个/秒(我自己实现的四种限流器)。被接受的总数:固定窗口 40,滑动窗口日志 30,滑动窗口计数 34,令牌桶 39。按客户端的每一秒:固定窗口 [20, 10, 10]、日志 [10, 10, 10]、计数 [16, 9, 9]、令牌桶 [19, 10, 10]。固定窗口和令牌桶的第一秒接受了接近 20 个:前者是客户端的头一秒横跨了两个窗口,后者是先用掉满桶的 10 个令牌再按每秒 10 个补;滑动窗口日志任何 1 秒内都不超过 10 个。", t=tl(S(1)), done=lidx(S(1), '滑动窗口日志:被接受'), mark=lidx(S(1), '固定窗口:被接受'), b=bars([['固定窗口', 40, '40'], ['滑动窗口日志', 30, '30'], ['滑动窗口计数', 34, '34'], ['令牌桶', 39, '39']], 42, mark=[0, 3], done=[1]), kv=KV([['固定窗口', '[20, 10, 10]'], ['滑动窗口日志', '[10, 10, 10]'], ['令牌桶', '[19, 10, 10](桶里先有 10 个)']], ['滑动窗口日志'])),
    step("窗口边界的突发:对齐到整秒,在一秒的 0.90–0.95 处连发 10 个,下一秒的 0.05–0.10 处再连发 10 个(总跨度约 0.15 秒),每种重复 5 次:固定窗口两批都被接受,合计 20 个(5 次都是);滑动窗口日志和滑动窗口计数后一批 0 个,合计 10 个;令牌桶后一批 1 个(桶在这 0.15 秒里补了约 1 个令牌),合计 11 个。固定窗口在窗口边界附近可以让 0.15 秒内通过两倍的限额。", t=tl(S(2)), done=lidx(S(2), '固定窗口:每次'), mark=lidx(S(2), '令牌桶:每次'), b=bars([['固定窗口:0.15 秒内被接受', 20, '20'], ['滑动窗口日志', 10, '10'], ['滑动窗口计数', 10, '10'], ['令牌桶', 11, '11']], 22, mark=[0], done=[1, 2, 3]), kv=KV([['固定窗口', '20 个(2 倍限额)'], ['滑动窗口日志/计数', '10 个'], ['令牌桶', '11 个']], ['固定窗口'])),
    step("收到 429 就按 Retry-After 等待再重试同一个请求,连续取 25 个页面,对比标准的整秒 Retry-After(服务器向上取整)和我自定义的毫秒头 X-Retry-After-Ms:固定窗口 2.02 秒对 1.90 秒(都是 27 个请求、2 个 429);滑动窗口日志 2.01 秒对 2.01 秒;滑动窗口计数 4.04 秒(29 个请求、4 个 429)对 2.58 秒(35 个请求、10 个 429);令牌桶 2.02 秒(27 个请求)对 1.50 秒(40 个请求、15 个 429)。整秒的 Retry-After 让需要等 0.1 秒的客户端等满 1 秒,代价是时间;精确的等待值更快,但发出的请求和 429 更多。", t=tl(S(3)), done=lidx(S(3), '令牌桶:整秒'), mark=lidx(S(3), '滑动窗口计数:整秒'), b=bars([['滑动窗口计数:整秒 Retry-After 用时 秒', 4.04, '4.04'], ['滑动窗口计数:毫秒值 用时 秒', 2.58, '2.58'], ['令牌桶:整秒 用时 秒', 2.02, '2.02'], ['令牌桶:毫秒值 用时 秒', 1.50, '1.50']], 4.2, mark=[0], done=[3]), kv=KV([['滑动窗口计数', '整秒 4.04 秒,毫秒 2.58 秒'], ['令牌桶', '整秒 2.02 秒,毫秒 1.50 秒'], ['毫秒值的代价', '令牌桶多发到 40 个请求(15 个 429)']], ['令牌桶'])),
    step("对令牌桶(速率 10/秒、桶容量 5)取 60 个页面,每个必须成功一次,三种客户端:429 后立刻重试——用时 5.50 秒,发出 15791 个请求(429 有 15731 个);429 后按 Retry-After(毫秒)等待——用时 5.50 秒,发出 115 个请求(429 有 55 个);按速率每 100 ms 发一个——用时 5.90 秒,发出 60 个请求(429 为 0)。三种用时差不多(速率就是 10 个/秒),但立刻重试多发了 260 倍的请求,服务器要处理这么多 429。", t=tl(S(4)), done=lidx(S(4), '匀速 100 ms 一个'), mark=lidx(S(4), '429 后立刻重试'), b=bars([['立刻重试:发出的请求', 15791, '15791'], ['按 Retry-After 等待:发出的请求', 115, '115'], ['匀速 100 ms:发出的请求', 60, '60']], 16000, mark=[0], done=[2]), kv=KV([['立刻重试', '15791 个请求,用时 5.50 秒'], ['按 Retry-After 等', '115 个请求,5.50 秒'], ['匀速 100 ms', '60 个请求,5.90 秒']], ['匀速 100 ms'])),
    step("4 个线程共用一个限流 key(令牌桶 速率 10/秒、桶容量 10),各自不停地发,收到 429 立刻重试,持续 3 秒:每个线程的(被接受, 被拒绝)是 (12, 1868)、(10, 1854)、(7, 1880)、(10, 1849);被接受合计 39(3 秒内最多约 10 + 3×10 = 40),被拒绝合计 7451。几个线程共用同一个额度,总数不变,线程多了只是各自拿到的少了,而且份额不均(7 到 12 个)。", t=tl(S(5)), done=lidx(S(5), '每个线程'), b=bars([['线程 1 被接受', 12, '12'], ['线程 2 被接受', 10, '10'], ['线程 3 被接受', 7, '7'], ['线程 4 被接受', 10, '10']], 14, done=[0, 1, 2, 3]), kv=KV([['被接受合计', '39(约等于 10 + 3×10)'], ['被拒绝合计', '7451'], ['各线程份额', '7 到 12 个,不均']], ['被接受合计'])),
    step("不知道服务器限多少时,用 AIMD 调速(从 2 个/秒起,每 1 秒没遇到 429 就加 1 个/秒,遇到 429 就减半),服务器限制 10 个/秒,跑 12 秒:固定窗口速率升到 12 时遇到 1 个 429,减半到 6,后 6 秒平均每秒被接受 8.3 个(共发出 77 个);滑动窗口日志升到 11 遇到 1 个 429,减到 5.5,后 6 秒 7.3 个;滑动窗口计数升到 10 遇到 1 个 429,减到 5,后 6 秒 7.0 个;令牌桶一直升到 13 都没遇到 429(桶里有 10 个令牌可以透支),后 6 秒 10.0 个。12 秒太短,没有看到完整的锯齿,只能说窗口类的限流在越过限额的那一刻就拒绝,而令牌桶让客户端的速率超过限额一段时间才拒绝。", t=tl(S(6)), done=lidx(S(6), '令牌桶:每秒调整后'), mark=lidx(S(6), '固定窗口:每秒调整后'), b=bars([['固定窗口:后 6 秒被接受/秒', 8.3, '8.3'], ['滑动窗口日志', 7.3, '7.3'], ['滑动窗口计数', 7.0, '7.0'], ['令牌桶', 10.0, '10.0']], 11, mark=[2], done=[3]), kv=KV([['窗口类', '越过限额就拒绝,减半后偏低'], ['令牌桶', '12 秒内没遇到 429,速率到 13'], ['观察时间', '12 秒,没看到完整锯齿']], ['令牌桶'])),
]
A = mkartp('p68', 68, '爬虫,限流,429,Retry-After,固定窗口,滑动窗口,令牌桶,AIMD,Python,真实验证,动画演示',
    '自己实现固定窗口、滑动窗口日志、滑动窗口计数、令牌桶四种限流器,从客户端看:固定窗口在边界附近 0.15 秒内放过两倍限额(20 对 10);整秒的 Retry-After 让客户端多等;429 后立刻重试多发 260 倍请求;AIMD 在窗口类限流下偏低。',
    '爬虫被限流时,服务器返回 429。限流有几种常见的实现,从客户端看行为各不相同。这篇在本机用四种自己实现的限流器,量一量边界突发、Retry-After 的取整、重试方式和自适应调速的实际表现。',
    [('20 对 10', '窗口边界附近 0.15 秒内连发 20 个请求:固定窗口全放过,滑动窗口日志/计数只放过 10 个'), ('15791 对 60', '令牌桶限速 10 个/秒时取 60 个页面:429 后立刻重试发出的请求数 与 匀速 100 ms 一个发出的请求数'), ('4.04 对 2.58 秒', '滑动窗口计数下取 25 个页面:按整秒 Retry-After 等待 与 按精确毫秒等待 的用时')],
    [('四种限流的行为', '<p>固定窗口按整点切窗口,实现最简单;滑动窗口日志记录每个请求的时间,任何 1 秒内都不超过限额;滑动窗口计数用上一个窗口的加权估算;令牌桶允许攒满桶后的突发,之后按速率放行。从客户端匀速发 30 个/秒、限额 10 个/秒,3 秒内被接受的总数分别是 40、30、34、39。</p>'),
     ('固定窗口的边界', '<p>在窗口边界附近,固定窗口两个窗口的额度可以连着用:0.15 秒内放过了 20 个,是限额的两倍。滑动窗口放过 10 个,令牌桶放过 11 个。如果你在帮服务器设计限流,这是固定窗口的缺点;如果你在写爬虫,别指望靠边界多拿额度——服务器的实现你并不知道。</p>'),
     ('Retry-After', '<p>按 RFC,Retry-After 是整秒数。服务器把 0.1 秒向上取整成 1 秒,守规矩的客户端就多等了 0.9 秒(滑动窗口计数下 4.04 秒对 2.58 秒)。精确的等待值更快,但发出的请求更多。服务器有 Retry-After 就应该遵守(见第 31 篇)。</p>'),
     ('重试方式', '<p>429 后立刻重试没有任何节制:实验里取 60 个页面发出了 15791 个请求,对服务器是一次小规模的压力,而且用时并没有更短。按速率发,或者按 Retry-After 等待,请求数少两个数量级,用时一样。</p>'),
     ('共用额度', '<p>限流通常按客户端标识(IP、账号等)计算,同一个标识下的多个线程共用一个额度。4 个线程加起来仍是约 39 个,每个线程只拿到 7 到 12 个。线程多了不会让总量变多,只会让 429 更多。</p>'),
     ('自适应调速', '<p>不知道限额时可以用 AIMD(加性增、乘性减):没遇到 429 就慢慢加速,遇到就减半。实验里窗口类限流在越过限额的那一刻就拒绝,减半之后平均速率偏低(7 到 8.3 个/秒);令牌桶因为桶里有余量,速率到 13 个/秒都没被拒绝。实验只跑了 12 秒,没看到完整的锯齿。</p>')],
    steps,
    [ENV_P + '。服务器是本机的 Srv,四种限流器都是我自己实现的(没有套用任何真实站点的规则;限额 10 个/秒,窗口 1 秒,令牌桶的容量按各节所写),同一个服务器线程里加锁;客户端是 requests Session;429 响应带整秒的 Retry-After(向上取整)和我自定义的 X-Retry-After-Ms;第一、三、四、五、六节各一次,第二节每种重复 5 次;窗口对齐用的是 time.time() 的整秒',
     '没有验证:真实站点的限流实现(它们常常按 IP、账号、接口分别计数,还有突发保护和黑名单);分布式限流(多个服务器节点共享计数)的误差;Retry-After 用 HTTP 日期格式时的处理;X-RateLimit-* 头(各家格式不一,没有标准);AIMD 跑足够长时间后的稳态速率;漏桶(Leaky bucket)限流;被限流后对账号或 IP 的惩罚性封禁'],
    '服务端限流')
